const incoming = ($json.body && typeof $json.body === 'object')
  ? $json.body
  : $json;

const text = (value, max = 2000) =>
  String(value ?? '').trim().slice(0, max);

const bool = (value, fallback = false) => {
  if (value === undefined || value === null || value === '') return fallback;
  return value === true || ['true', '1', 'yes', 'on'].includes(String(value).trim().toLowerCase());
};

const clientId = text(
  incoming.clientId ??
  incoming['client-id'] ??
  incoming.projectId ??
  incoming['project-id'],
  120
).toLowerCase();

const from = text(incoming.from ?? incoming.startDate, 10);
const to = text(incoming.to ?? incoming.endDate, 10);
const question = text(incoming.question ?? incoming.message, 2000);
const pageContextRaw = text(incoming.pageContext ?? incoming.context ?? 'auto', 30).toLowerCase();
const debug = bool(incoming.debug, false);

const cacheEnabled = bool(incoming.cacheEnabled, true);
const forceRefresh = bool(
  incoming.forceRefresh ??
  incoming.refresh ??
  incoming.bypassCache,
  false
);
const allowStale = bool(incoming.allowStale, false);
const cacheSchemaVersion = 'parent-v5-compact-gsc1';

const allowedContexts = new Set(['auto', 'overview', 'ga4', 'gsc', 'ai']);
const pageContext = allowedContexts.has(pageContextRaw) ? pageContextRaw : 'auto';

const datePattern = /^\d{4}-\d{2}-\d{2}$/;
const validDate = (value) => {
  if (!datePattern.test(value)) return false;
  const date = new Date(`${value}T00:00:00Z`);
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === value;
};

const errors = [];

if (!clientId) errors.push('clientId is required.');
if (!validDate(from)) errors.push('from must be a valid YYYY-MM-DD date.');
if (!validDate(to)) errors.push('to must be a valid YYYY-MM-DD date.');

if (validDate(from) && validDate(to)) {
  const start = new Date(`${from}T00:00:00Z`);
  const end = new Date(`${to}T00:00:00Z`);
  const days = Math.floor((end - start) / 86400000) + 1;

  if (start > end) errors.push('from must be on or before to.');
  if (days > 366) errors.push('The requested date range cannot exceed 366 days.');
}

if (question.length < 3) {
  errors.push('question must contain at least 3 characters.');
}

const rawConversation = Array.isArray(incoming.conversation)
  ? incoming.conversation.slice(-8)
  : [];

const conversation = rawConversation
  .map((item) => {
    const roleRaw = text(item?.role ?? 'user', 20).toLowerCase();
    const role = roleRaw === 'assistant' || roleRaw === 'model'
      ? 'assistant'
      : 'user';
    const content = text(
      item?.content ?? item?.text ?? item?.message,
      1200
    );
    return content ? { role, content } : null;
  })
  .filter(Boolean);

const requestId = text(incoming.requestId, 160) ||
  `ai_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;

return [{
  json: {
    ok: errors.length === 0,
    status: errors.length === 0 ? 200 : 400,
    code: errors.length === 0 ? null : 'VALIDATION_ERROR',
    errors,
    requestId,
    clientId,
    from,
    to,
    question,
    pageContext,
    conversation,
    debug,
    cacheEnabled,
    forceRefresh,
    allowStale,
    cacheSchemaVersion,
    directCacheAllowed: cacheEnabled && !forceRefresh,
    cacheRequest: {
      action: 'get',
      clientId,
      from,
      to,
      view: 'ai',
      schemaVersion: cacheSchemaVersion,
      allowStale,
      requestId
    },
    parentRequest: {
      'client-id': clientId,
      from,
      to,
      view: 'ai',
      debug,
      cacheEnabled,
      forceRefresh,
      allowStale
    }
  }
}];

const source = $input.first().json || {};
const request = $('Validate & Normalize Request').first().json;

const directCacheHit =
  source.ok === true &&
  source.hit === true &&
  source.payload &&
  typeof source.payload === 'object';

const parent = directCacheHit ? source.payload : source;

const evidenceCache = directCacheHit
  ? {
      source: 'snapshot_cache',
      hit: true,
      stale: source.cache?.stale === true,
      snapshotKey: source.cache?.snapshotKey || null,
      cacheKey: source.cache?.cacheKey || null,
      generationId: source.cache?.generationId || null,
      generatedAt: source.cache?.generatedAt || null,
      expiresAt: source.cache?.expiresAt || null,
      schemaVersion: source.cache?.schemaVersion || request.cacheSchemaVersion
    }
  : {
      source: 'parent_orchestrator',
      hit: parent.meta?.cache?.hit === true,
      stale: parent.meta?.cache?.stale === true,
      stored: parent.meta?.cache?.stored === true,
      snapshotKey: parent.meta?.cache?.snapshotKey || null,
      cacheKey: parent.meta?.cache?.cacheKey || null,
      generationId: parent.meta?.cache?.generationId || null,
      generatedAt: parent.meta?.cache?.generatedAt || null,
      expiresAt: parent.meta?.cache?.expiresAt || null,
      schemaVersion: parent.meta?.cache?.schemaVersion || request.cacheSchemaVersion
    };

if (parent.ok !== true || !parent.analyticsEvidence) {
  return [{
    json: {
      ready: false,
      status: 502,
      code: 'ANALYTICS_EVIDENCE_ERROR',
      error:
        parent.error ||
        source.error ||
        'Cached evidence was unavailable and the Parent Orchestrator did not return AI analytics evidence.',
      requestId: request.requestId,
      evidenceCache,
      parentResponse: request.debug ? source : undefined
    }
  }];
}

const ga4 = parent.analyticsEvidence.ga4 || {};
const gsc = parent.analyticsEvidence.gsc || {};
const rootKpis = parent.kpis || {};
const q = request.question.toLowerCase();

const containsAny = (terms) => terms.some((term) => q.includes(term));

let intent = 'combined_overview';
let domain = 'combined';

const aiTerms = [
  'chatgpt', 'gemini', 'perplexity', 'copilot', 'claude',
  'ai traffic', 'ai referral', 'ai assistant', 'llm', 'aeo'
];
const landingTerms = [
  'landing page', 'landing pages', 'landed on', 'landing url',
  'landing urls', 'which page', 'which pages', 'specific page',
  'specific pages', 'receiving traffic', 'top page', 'top pages'
];
const sourceTerms = [
  'source', 'sources', 'came from', 'coming from', 'originated from',
  'referrer', 'referrers', 'referral source', 'traffic source'
];

const hasAiTerm = containsAny(aiTerms);
const hasLandingTerm = containsAny(landingTerms);
const hasSourceTerm = containsAny(sourceTerms);
const asksWhereAiCameFrom =
  hasAiTerm &&
  (
    /^where\b/.test(q) ||
    /\bwhere\s+(?:did|does|is|was|were)?\s*.*\b(?:ai|chatgpt|gemini|perplexity|copilot|claude)\b/.test(q) ||
    /\b(?:ai|chatgpt|gemini|perplexity|copilot|claude).*\b(?:came|coming|originated)\s+from\b/.test(q)
  );
const asksForAiLandingPages =
  hasAiTerm &&
  (hasLandingTerm || /\b(?:landing|landed|page|pages|url|urls)\b/.test(q));

if (asksForAiLandingPages) {
  intent = 'ai_landing_pages';
  domain = 'ga4';
} else if (hasAiTerm && (hasSourceTerm || asksWhereAiCameFrom)) {
  intent = 'ai_sources';
  domain = 'ga4';
} else if (hasAiTerm) {
  intent = 'ai_traffic';
  domain = 'ga4';
} else if (containsAny(['conversion', 'conversions', 'engagement', 'engaged', 'duration', 'bounce'])) {
  intent = 'conversions_engagement';
  domain = 'ga4';
} else if (containsAny(['channel', 'source', 'medium', 'referral', 'direct traffic', 'organic social', 'paid search'])) {
  intent = 'channels_sources';
  domain = 'ga4';
} else if (containsAny(['device', 'desktop', 'mobile', 'tablet', 'country', 'countries', 'location', 'geography'])) {
  intent = 'devices_countries';
  domain = request.pageContext === 'gsc' ? 'gsc' : 'combined';
} else if (containsAny(['landing page', 'landing pages', 'page lost', 'page gained', 'pages lost', 'pages gained', 'best page', 'worst page'])) {
  intent = 'landing_pages';
  domain = containsAny(['click', 'impression', 'position', 'ranking', 'gsc', 'search']) ? 'gsc' : 'combined';
} else if (containsAny(['keyword', 'keywords', 'query', 'queries', 'ranking', 'rankings', 'position', 'ctr', 'impression', 'search console', 'gsc'])) {
  intent = 'queries_keywords';
  domain = 'gsc';
} else if (containsAny(['session', 'sessions', 'user', 'users', 'traffic', 'analytics', 'ga4'])) {
  intent = 'ga4_performance';
  domain = 'ga4';
}

if (request.pageContext === 'gsc') {
  if (intent === 'combined_overview') intent = 'gsc_visibility';
  if (['gsc_visibility', 'landing_pages', 'devices_countries'].includes(intent)) domain = 'gsc';
}
if (request.pageContext === 'ga4') {
  if (intent === 'combined_overview') intent = 'ga4_performance';
  if (['ga4_performance', 'landing_pages', 'devices_countries'].includes(intent)) domain = 'ga4';
}
if (request.pageContext === 'ai') {
  if (!['ai_traffic', 'ai_sources', 'ai_landing_pages'].includes(intent)) {
    intent = 'ai_traffic';
  }
  domain = 'ga4';
}

const stopWords = new Set([
  'what', 'which', 'where', 'when', 'why', 'how', 'the', 'a', 'an', 'and', 'or',
  'of', 'to', 'for', 'in', 'on', 'with', 'from', 'most', 'more', 'less', 'show',
  'tell', 'give', 'me', 'our', 'this', 'that', 'these', 'those', 'during', 'period',
  'current', 'previous', 'month', 'report', 'data', 'performance'
]);

const tokens = [...new Set(
  q.replace(/[^\p{L}\p{N}\s/_-]/gu, ' ')
    .split(/\s+/)
    .map((token) => token.trim())
    .filter((token) => token.length >= 3 && !stopWords.has(token))
)].slice(0, 15);

const num = (value) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};

const pick = (obj, keys) => {
  const result = {};
  for (const key of keys) {
    if (obj && obj[key] !== undefined && obj[key] !== null) result[key] = obj[key];
  }
  return result;
};

const compactGa4 = (row) => pick(row, [
  'name', 'source', 'medium', 'landingPage', 'country', 'device',
  'sessions', 'prevSessions', 'sessionsChange', 'users', 'prevUsers',
  'newUsers', 'prevNewUsers', 'engagedSessions', 'prevEngagedSessions',
  'engagementRate', 'prevEngagementRate', 'conversions', 'prevConversions',
  'pageViews', 'prevPageViews', 'averageSessionDuration',
  'prevAverageSessionDuration', 'status', 'classificationConfidence'
]);

const compactGsc = (row) => pick(row, [
  'query', 'page', 'name', 'country', 'device', 'searchAppearance',
  'clicks', 'prevClicks', 'clickDelta', 'clicksChange',
  'impressions', 'prevImpressions', 'impressionDelta', 'impressionsChange',
  'ctr', 'prevCtr', 'ctrChange', 'position', 'prevPosition',
  'positionChange', 'status', 'classificationConfidence'
]);

const scoreRow = (row) => {
  if (!tokens.length) return 0;
  const haystack = [
    row?.name, row?.query, row?.page, row?.landingPage,
    row?.source, row?.medium, row?.country, row?.device
  ].filter(Boolean).join(' ').toLowerCase();
  return tokens.reduce((score, token) => score + (haystack.includes(token) ? 1 : 0), 0);
};

const selectRows = (rows, limit, compact) => {
  const source = Array.isArray(rows) ? rows : [];
  if (!tokens.length) return source.slice(0, limit).map(compact);
  const scored = source.map((row, index) => ({ row, index, score: scoreRow(row) }));
  const matched = scored.filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score || a.index - b.index)
    .slice(0, limit);
  if (matched.length >= Math.min(3, limit)) return matched.map((item) => compact(item.row));
  const used = new Set(matched.map((item) => item.index));
  const fill = scored.filter((item) => !used.has(item.index)).slice(0, limit - matched.length);
  return [...matched, ...fill].map((item) => compact(item.row));
};

const sortRows = (rows, field, desc = true) =>
  [...(Array.isArray(rows) ? rows : [])].sort((a, b) => {
    const av = num(a?.[field]) ?? 0;
    const bv = num(b?.[field]) ?? 0;
    return desc ? bv - av : av - bv;
  });

const selected = {
  ga4: {
    kpis: ga4.kpis || {},
    channelLeaders: [],
    landingPages: [],
    sourceMedium: [],
    devices: [],
    countries: [],
    aiAssistantTraffic: null,
    dataQuality: ga4.dataQuality || null,
    warnings: Array.isArray(ga4.warnings) ? ga4.warnings.slice(0, 8) : []
  },
  gsc: {
    totals: gsc.totals || {},
    queryWinners: [],
    queryLosers: [],
    pageWinners: [],
    pageLosers: [],
    rankingGainers: [],
    rankingLosers: [],
    ctrGainers: [],
    ctrLosers: [],
    opportunities: [],
    devices: [],
    countries: [],
    pageQueries: [],
    positionBuckets: Array.isArray(gsc.positionBuckets) ? gsc.positionBuckets : [],
    queryStatusCounts: gsc.queryStatusCounts || {},
    pageStatusCounts: gsc.pageStatusCounts || {},
    coverage: gsc.coverage || {},
    dataQuality: gsc.dataQuality || null,
    warnings: Array.isArray(gsc.warnings) ? gsc.warnings.slice(0, 8) : []
  }
};

if (domain === 'ga4' || domain === 'combined') {
  selected.ga4.channelLeaders = selectRows(ga4.channelLeaders, intent === 'channels_sources' ? 12 : 7, compactGa4);
  selected.ga4.landingPages = selectRows(ga4.landingPages, intent === 'landing_pages' ? 10 : 7, compactGa4);
  selected.ga4.sourceMedium = selectRows(ga4.sourceMedium, intent === 'channels_sources' ? 10 : 7, compactGa4);
  selected.ga4.devices = selectRows(ga4.devices, 5, compactGa4);
  selected.ga4.countries = selectRows(ga4.countries, intent === 'devices_countries' ? 10 : 6, compactGa4);
  selected.ga4.aiAssistantTraffic = ga4.aiAssistantTraffic || null;
}

if (domain === 'gsc' || domain === 'combined') {
  selected.gsc.queryWinners = selectRows(gsc.queryWinners, intent === 'queries_keywords' ? 10 : 6, compactGsc);
  selected.gsc.queryLosers = selectRows(gsc.queryLosers, intent === 'queries_keywords' ? 10 : 6, compactGsc);
  selected.gsc.pageWinners = selectRows(gsc.pageWinners, intent === 'landing_pages' ? 8 : 5, compactGsc);
  selected.gsc.pageLosers = selectRows(gsc.pageLosers, intent === 'landing_pages' ? 8 : 5, compactGsc);
  selected.gsc.rankingGainers = selectRows(gsc.rankingGainers, intent === 'queries_keywords' ? 8 : 5, compactGsc);
  selected.gsc.rankingLosers = selectRows(gsc.rankingLosers, intent === 'queries_keywords' ? 8 : 5, compactGsc);
  selected.gsc.ctrGainers = selectRows(gsc.ctrGainers, 6, compactGsc);
  selected.gsc.ctrLosers = selectRows(gsc.ctrLosers, 6, compactGsc);
  selected.gsc.opportunities = selectRows(gsc.opportunities, 12, compactGsc);
  selected.gsc.devices = selectRows(gsc.devices, 5, compactGsc);
  selected.gsc.countries = selectRows(gsc.countries, intent === 'devices_countries' ? 10 : 6, compactGsc);
  selected.gsc.pageQueries = selectRows(gsc.pageQueries, intent === 'landing_pages' || intent === 'queries_keywords' ? 10 : 6, compactGsc);
}

if (intent === 'conversions_engagement') {
  selected.ga4.channelLeaders = sortRows(ga4.channelLeaders, 'conversions').slice(0, 8).map(compactGa4);
  selected.ga4.landingPages = sortRows(ga4.landingPages, 'conversions').slice(0, 10).map(compactGa4);
}

if (['ai_traffic', 'ai_sources', 'ai_landing_pages'].includes(intent)) {
  selected.ga4 = {
    kpis: ga4.kpis || {},
    channelLeaders: [],
    landingPages: [],
    sourceMedium: [],
    devices: [],
    countries: [],
    aiAssistantTraffic: ga4.aiAssistantTraffic || null,
    dataQuality: ga4.dataQuality || null,
    warnings: Array.isArray(ga4.warnings) ? ga4.warnings.slice(0, 8) : []
  };
  selected.gsc = {
    totals: {},
    dataQuality: gsc.dataQuality || null,
    warnings: Array.isArray(gsc.warnings) ? gsc.warnings.slice(0, 4) : []
  };
}

const facts = [];
const addFact = (source, statement, data = {}, reliability = 'high') => {
  const id = `F${facts.length + 1}`;
  facts.push({ id, source, statement, data, reliability });
  return id;
};

const kpiLabels = {
  totalUsers: 'Total users',
  newUsers: 'New users',
  totalPageViews: 'Page views',
  conversions: 'Conversions',
  aiTraffic: 'AI referral sessions',
  sessions: 'Sessions',
  engagedSessions: 'Engaged sessions',
  engagementRate: 'Engagement rate',
  averageSessionDuration: 'Average session duration',
  gscClicks: 'GSC clicks',
  gscImpressions: 'GSC impressions',
  avgCtr: 'Average CTR',
  avgPosition: 'Average position',
  keywordsTop3: 'Keywords in positions 1 to 3 within returned rows',
  keywordsTop10: 'Keywords in positions 1 to 10 within returned rows',
  keywordsTop20: 'Keywords in positions 1 to 20 within returned rows',
  opportunityCount: 'Opportunity queries within returned rows'
};

const aiSpecificIntent = ['ai_traffic', 'ai_sources', 'ai_landing_pages'].includes(intent);

const allowedKpis = aiSpecificIntent
  ? []
  : domain === 'ga4'
    ? ['totalUsers', 'newUsers', 'sessions', 'engagedSessions', 'engagementRate', 'averageSessionDuration', 'conversions', 'aiTraffic']
    : domain === 'gsc'
      ? ['gscClicks', 'gscImpressions', 'avgCtr', 'avgPosition', 'keywordsTop3', 'keywordsTop10', 'keywordsTop20', 'opportunityCount']
      : ['totalUsers', 'sessions', 'engagementRate', 'conversions', 'gscClicks', 'gscImpressions', 'avgCtr', 'avgPosition'];

for (const key of allowedKpis) {
  const item = rootKpis[key];
  if (!item) continue;
  addFact(
    key.startsWith('gsc') || ['avgCtr', 'avgPosition', 'keywordsTop3', 'keywordsTop10', 'keywordsTop20', 'opportunityCount'].includes(key) ? 'GSC' : 'GA4',
    `${kpiLabels[key] || key}: ${item.value}${item.suffix || ''}, previous ${item.prev}${item.suffix || ''}, reported change ${item.change}${item.changeSuffix || ''}.`,
    { metric: key, current: item.value, previous: item.prev, change: item.change, suffix: item.suffix || '', changeSuffix: item.changeSuffix || '' },
    key.startsWith('keywords') || key === 'opportunityCount' ? 'limited_when_rows_truncated' : 'high'
  );
}

const rowFact = (source, row, label) => {
  const name = row.name || row.query || row.page || row.landingPage || row.country || row.device || 'Unknown';
  const statementParts = [`${label} "${name}"`];

  if (row.sessions !== undefined) {
    statementParts.push(`${row.sessions} session${Number(row.sessions) === 1 ? '' : 's'} vs ${row.prevSessions ?? 0}`);
  }
  if (row.sessionsChange !== undefined && row.sessionsChange !== null) {
    statementParts.push(`reported session change ${row.sessionsChange}%`);
  }

  if (row.clicks !== undefined) {
    statementParts.push(`${row.clicks} clicks vs ${row.prevClicks ?? 0}`);
  }
  if (row.clickDelta !== undefined && row.clickDelta !== null) {
    statementParts.push(`reported click delta ${row.clickDelta}`);
  }
  if (row.clicksChange !== undefined && row.clicksChange !== null) {
    statementParts.push(`reported click change ${row.clicksChange}%`);
  }

  if (row.impressions !== undefined) {
    statementParts.push(`${row.impressions} impressions vs ${row.prevImpressions ?? 0}`);
  }
  if (row.impressionDelta !== undefined && row.impressionDelta !== null) {
    statementParts.push(`reported impression delta ${row.impressionDelta}`);
  }
  if (row.impressionsChange !== undefined && row.impressionsChange !== null) {
    statementParts.push(`reported impression change ${row.impressionsChange}%`);
  }

  if (row.engagementRate !== undefined) {
    statementParts.push(`${row.engagementRate}% engagement rate`);
  }
  if (row.conversions !== undefined) {
    statementParts.push(`${row.conversions} conversions`);
  }

  if (row.position !== undefined) {
    statementParts.push(`position ${row.position} vs ${row.prevPosition ?? 0}`);
  }
  if (row.positionChange !== undefined && row.positionChange !== null) {
    statementParts.push(`reported position change ${row.positionChange} positions`);
  }

  if (row.ctr !== undefined) {
    statementParts.push(`${row.ctr}% CTR vs ${row.prevCtr ?? 0}%`);
  }
  if (row.ctrChange !== undefined && row.ctrChange !== null) {
    statementParts.push(`reported CTR change ${row.ctrChange} percentage points`);
  }

  return addFact(
    source,
    `${statementParts.join(', ')}.`,
    row,
    row.classificationConfidence || 'high'
  );
};

if (intent === 'channels_sources' || intent === 'ga4_performance' || intent === 'combined_overview') {
  selected.ga4.channelLeaders.slice(0, 5).forEach((row) => rowFact('GA4', row, 'Channel'));
  selected.ga4.sourceMedium.slice(0, 5).forEach((row) => rowFact('GA4', row, 'Source/medium'));
}
if (intent === 'landing_pages' || intent === 'ga4_performance' || intent === 'combined_overview') {
  selected.ga4.landingPages.slice(0, 5).forEach((row) => rowFact('GA4', row, 'Landing page'));
  selected.gsc.pageWinners.slice(0, 4).forEach((row) => rowFact('GSC', row, 'Page winner'));
  selected.gsc.pageLosers.slice(0, 4).forEach((row) => rowFact('GSC', row, 'Page loser'));
}
if (intent === 'queries_keywords' || intent === 'gsc_visibility' || intent === 'combined_overview') {
  // Put losses first so the most decision-relevant facts remain inside
  // the deterministic-fact cap.
  selected.gsc.queryLosers
    .slice(0, 5)
    .forEach((row) => rowFact('GSC', row, 'Query loser'));

  selected.gsc.rankingLosers
    .slice(0, 5)
    .forEach((row) => rowFact('GSC', row, 'Ranking loser'));

  selected.gsc.queryWinners
    .slice(0, 3)
    .forEach((row) => rowFact('GSC', row, 'Query winner'));

  selected.gsc.rankingGainers
    .slice(0, 3)
    .forEach((row) => rowFact('GSC', row, 'Ranking gainer'));

  selected.gsc.ctrLosers
    .slice(0, 3)
    .forEach((row) => rowFact('GSC', row, 'CTR loser'));

  selected.gsc.ctrGainers
    .slice(0, 3)
    .forEach((row) => rowFact('GSC', row, 'CTR gainer'));

  selected.gsc.opportunities
    .slice(0, 3)
    .forEach((row) => rowFact('GSC', row, 'Opportunity query'));
}
if (intent === 'conversions_engagement') {
  selected.ga4.channelLeaders.slice(0, 6).forEach((row) => rowFact('GA4', row, 'Channel'));
  selected.ga4.landingPages.slice(0, 6).forEach((row) => rowFact('GA4', row, 'Landing page'));
}
if (intent === 'devices_countries') {
  selected.ga4.devices.slice(0, 5).forEach((row) => rowFact('GA4', row, 'Device'));
  selected.ga4.countries.slice(0, 8).forEach((row) => rowFact('GA4', row, 'Country'));
  selected.gsc.devices.slice(0, 5).forEach((row) => rowFact('GSC', row, 'Device'));
  selected.gsc.countries.slice(0, 8).forEach((row) => rowFact('GSC', row, 'Country'));
}
if (['ai_traffic', 'ai_sources', 'ai_landing_pages'].includes(intent)) {
  const aiTraffic = ga4.aiAssistantTraffic || {};
  const aiKpis = aiTraffic.kpis || {};
  const preferredKpis = [
    'sessions', 'users', 'engagedSessions', 'engagementRate',
    'conversions', 'newUsers', 'pageViews', 'averageSessionDuration'
  ];
  const aiKpiLabels = {
    sessions: 'sessions',
    users: 'users',
    engagedSessions: 'engaged sessions',
    engagementRate: 'engagement rate',
    conversions: 'conversions',
    newUsers: 'new users',
    pageViews: 'page views',
    averageSessionDuration: 'average session duration'
  };

  for (const key of preferredKpis) {
    const item = aiKpis[key];
    if (!item || typeof item !== 'object' || item.value === undefined) continue;
    addFact(
      'GA4 AI referral traffic',
      `AI referral ${aiKpiLabels[key] || key}: ${item.value}${item.suffix || ''}, previous ${item.prev ?? 0}${item.suffix || ''}, reported change ${item.change ?? 0}${item.changeSuffix || ''}.`,
      { metric: key, ...item }
    );
  }

  const sourceRows = (aiTraffic.sources || []).map(compactGa4);
  const landingRows = (aiTraffic.landingPages || []).map(compactGa4);

  if (intent === 'ai_landing_pages' && landingRows.length === 0) {
    addFact(
      'GA4 AI referral traffic',
      'No AI referral landing-page rows were available in the cached GA4 evidence for the selected period.',
      { dataset: 'aiLandingPages', availableRows: 0 }
    );
