  if (intent === 'ai_sources' && sourceRows.length === 0) {
    addFact(
      'GA4 AI referral traffic',
      'No AI referral source rows were available in the cached GA4 evidence for the selected period.',
      { dataset: 'aiSources', availableRows: 0 }
    );
  }

  if (intent === 'ai_landing_pages') {
    landingRows.slice(0, 12).forEach((row) =>
      rowFact('GA4 AI referral traffic', row, 'AI referral landing page')
    );
  } else if (intent === 'ai_sources') {
    sourceRows.slice(0, 12).forEach((row) =>
