const ga4DataQuality = ga4.dataQuality || {};
const gscDataQuality = gsc.dataQuality || {};

const ga4TruncatedReports = Array.isArray(ga4DataQuality.truncatedReports)
  ? ga4DataQuality.truncatedReports
  : [];
const gscLimitHits = Array.isArray(gscDataQuality.limitHits)
  ? gscDataQuality.limitHits
  : [];

const ga4ReportsByIntent = {
  ai_traffic: ['aiSources', 'aiLandingPages', 'aiCountries'],
  ai_sources: ['aiSources'],
  ai_landing_pages: ['aiLandingPages'],
  conversions_engagement: ['channels', 'landingPages'],
  channels_sources: ['channels', 'sourceMedium'],
  devices_countries: ['countries'],
  landing_pages: ['landingPages'],
  ga4_performance: ['channels', 'landingPages', 'sourceMedium'],
  combined_overview: ['channels', 'landingPages', 'sourceMedium', 'countries']
};

const gscDatasetsByIntent = {
  queries_keywords: ['queries', 'pageQueries'],
  gsc_visibility: ['queries', 'pageQueries'],
  devices_countries: ['countries', 'devices'],
  landing_pages: ['queries', 'pageQueries'],
  combined_overview: ['queries', 'countries', 'pageQueries']
};

const ga4RelevantReports = new Set(
  ga4ReportsByIntent[intent] || ga4ReportsByIntent.ga4_performance
);
const gscRelevantDatasets = new Set(
  gscDatasetsByIntent[intent] || gscDatasetsByIntent.gsc_visibility
);

const relevantGa4Truncations = ga4TruncatedReports.filter((item) =>
  ga4RelevantReports.has(String(item?.report || ''))
);
const relevantGscLimitHits = gscLimitHits.filter((item) =>
  gscRelevantDatasets.has(String(item?.dataset || ''))
);

const usesGa4 = domain === 'ga4' || domain === 'combined';
const usesGsc = domain === 'gsc' || domain === 'combined';

const ga4EvidencePartial =
  usesGa4 &&
  (
    relevantGa4Truncations.length > 0 ||
    (
      ga4DataQuality.partial === true &&
      ga4TruncatedReports.length === 0
    )
  );

const gscEvidencePartial =
  usesGsc &&
  (
    relevantGscLimitHits.length > 0 ||
    (
      gscDataQuality.partial === true &&
      gscLimitHits.length === 0
    )
  );

const evidencePartial = ga4EvidencePartial || gscEvidencePartial;

const limitations = [];
const addLimitation = (message) => {
  const value = String(message || '').trim();
  if (value && !limitations.includes(value)) limitations.push(value);
};

const periodsFor = (rows) => {
  const periods = [...new Set(
    rows.map((item) => String(item?.period || '').trim()).filter(Boolean)
  )];
  if (!periods.length) return '';
  if (periods.length === 1) return ` for the ${periods[0]} period`;
  return ' for the current and previous periods';
};

if (usesGa4) {
  const ga4Labels = {
    landingPages: 'landing-page',
    sourceMedium: 'source/medium',
    countries: 'country',
    channels: 'channel',
    aiSources: 'AI-source',
    aiLandingPages: 'AI landing-page',
    aiCountries: 'AI-country'
  };

  for (const report of ga4RelevantReports) {
    const rows = relevantGa4Truncations.filter((item) => item.report === report);
    if (!rows.length) continue;
    const label = ga4Labels[report] || report;
    addLimitation(
      `GA4 ${label} rows reached configured limits${periodsFor(rows)}, so this part of the evidence is partial.`
    );
  }

  if (['ai_traffic', 'ai_sources', 'ai_landing_pages'].includes(intent)) {
    const aiWarning = (Array.isArray(ga4.warnings) ? ga4.warnings : [])
