    if (aiWarning) addLimitation(aiWarning);

    const aiTraffic = ga4.aiAssistantTraffic || {};
    if (intent === 'ai_landing_pages' && !(Array.isArray(aiTraffic.landingPages) && aiTraffic.landingPages.length)) {
      addLimitation('No AI referral landing-page rows were available in the cached GA4 evidence for the selected period.');
