const rowIdentity = (row) => String(
  row?.landingPage ||
  row?.name ||
  [row?.source, row?.medium].filter(Boolean).join(' / ')
).trim().toLowerCase();

const factIdForRow = (row) => {
  const identity = rowIdentity(row);
  if (!identity) return null;
  const match = cappedFacts.find((fact) => rowIdentity(fact?.data) === identity);
  return match?.id || null;
};

const tableRows = (rows, entityKey) => rows
  .map((row) => {
