  aiEngagement: aiKpis.engagementRate?.value !== undefined,
  aiConversions: aiKpis.conversions?.value !== undefined
};

const answerableTopics = [];
if (evidenceAvailability.aiSources > 0) answerableTopics.push('ai_sources');
if (evidenceAvailability.aiLandingPages > 0) answerableTopics.push('ai_landing_pages');
if (evidenceAvailability.aiSessions) answerableTopics.push('ai_sessions');
if (evidenceAvailability.aiEngagement) answerableTopics.push('ai_engagement');
if (evidenceAvailability.aiConversions) answerableTopics.push('ai_conversions');

const suggestedQuestionOptions = [];
