    ? `The analytics evidence was collected successfully, but the language model response could not be validated. Key verified facts: ${fallbackFacts.map((fact) => fact.statement).join(' ')}`
    : 'The analytics evidence was collected successfully, but the language model response could not be validated.';

  return [{
