}

const facts = Array.isArray(prepared.deterministicFacts)
  ? prepared.deterministicFacts
  : [];

const factMap = new Map(
  facts.map((fact) => [String(fact.id), fact])
);

const factIds = new Set(factMap.keys());

const validIds = (values) => [
  ...new Set(
    (Array.isArray(values) ? values : [])
      .map(String)
      .filter((id) => factIds.has(id))
  )
];

const normalizeWording = (value) => {
  let text = String(value || '').trim();

  const replacements = [
    [
      /\bincreased by\s+[-−]\s*(\d[\d,]*(?:\.\d+)?)(\s*(?:%|percentage points?|pp|positions?|seconds?|sec)?)\b/gi,
      'decreased by $1$2'
    ],
    [
      /\bincreasing by\s+[-−]\s*(\d[\d,]*(?:\.\d+)?)(\s*(?:%|percentage points?|pp|positions?|seconds?|sec)?)\b/gi,
      'decreasing by $1$2'
    ],
    [
      /\ban increase of\s+[-−]\s*(\d[\d,]*(?:\.\d+)?)(\s*(?:%|percentage points?|pp|positions?|seconds?|sec)?)\b/gi,
      'a decrease of $1$2'
    ],
    [
      /\bdecreased by\s+[-−]\s*(\d[\d,]*(?:\.\d+)?)(\s*(?:%|percentage points?|pp|positions?|seconds?|sec)?)\b/gi,
      'increased by $1$2'
    ],
    [
      /\bdecreasing by\s+[-−]\s*(\d[\d,]*(?:\.\d+)?)(\s*(?:%|percentage points?|pp|positions?|seconds?|sec)?)\b/gi,
      'increasing by $1$2'
    ],
    [
      /\ba decrease of\s+[-−]\s*(\d[\d,]*(?:\.\d+)?)(\s*(?:%|percentage points?|pp|positions?|seconds?|sec)?)\b/gi,
      'an increase of $1$2'
    ],
    [/\bAI Assistant channel\b/gi, 'AI referral traffic'],
    [/\bAI Assistant traffic\b/gi, 'AI referral traffic'],
    [/\bAI Assistant sessions\b/gi, 'AI referral sessions'],
    [/\bAI traffic\b/gi, 'AI referral traffic']
  ];

  for (const [pattern, replacement] of replacements) {
    text = text.replace(pattern, replacement);
  }

  return text.replace(/\s{2,}/g, ' ').trim();
};

const numberPattern = /[-−+]?\d[\d,]*(?:\.\d+)?/g;

const normalizeNumber = (value) => {
  const raw = String(value || '')
    .replace(/,/g, '')
    .replace(/−/g, '-')
    .replace(/^\+/, '');

  const parsedNumber = Number(raw);
  if (!Number.isFinite(parsedNumber)) return null;
  return String(Math.abs(parsedNumber));
};

const extractNumbers = (value) => {
  const matches = String(value || '').match(numberPattern) || [];
  return matches
    .map(normalizeNumber)
    .filter(Boolean);
};

const collectPrimitiveText = (value, output = []) => {
  if (value === null || value === undefined) return output;

  if (
    typeof value === 'string' ||
    typeof value === 'number' ||
    typeof value === 'boolean'
  ) {
    output.push(String(value));
    return output;
  }

  if (Array.isArray(value)) {
    value.forEach((item) => collectPrimitiveText(item, output));
    return output;
  }

  if (typeof value === 'object') {
    Object.values(value).forEach((item) =>
      collectPrimitiveText(item, output)
    );
  }

  return output;
};

const requestNumberSet = new Set(
  extractNumbers(`${request.from || ''} ${request.to || ''}`)
);

const allowedNumberSet = (ids) => {
  const allowed = new Set(requestNumberSet);

  for (const id of ids) {
    const fact = factMap.get(id);
    if (!fact) continue;

    const values = [
      fact.statement,
      ...collectPrimitiveText(fact.data)
    ];

    for (const value of values) {
      extractNumbers(value).forEach((number) => allowed.add(number));
    }
  }

  return allowed;
};

const unsupportedNumbers = (text, ids) => {
  const numbers = extractNumbers(text);
  if (!numbers.length) return [];

  const allowed = allowedNumberSet(ids);
  return numbers.filter((number) => !allowed.has(number));
};

const normalizeEntity = (value) => String(value || '')
  .trim()
  .replace(/[),.;:!?]+$/g, '')
  .toLowerCase();

const extractEntities = (value) => {
  const text = String(value || '');
  const entities = new Set();

  const fullUrls = text.match(/https?:\/\/[^\s<>()"']+/gi) || [];
  for (const rawUrl of fullUrls) {
    const normalized = normalizeEntity(rawUrl);
    if (normalized) entities.add(normalized);
    try {
      const parsedUrl = new URL(rawUrl.replace(/[),.;:!?]+$/g, ''));
      if (parsedUrl.hostname) entities.add(parsedUrl.hostname.toLowerCase());
      if (parsedUrl.pathname && parsedUrl.pathname !== '/') {
        entities.add(normalizeEntity(parsedUrl.pathname));
      }
    } catch {}
  }

  const domains = text.match(/\b(?:[a-z0-9-]+\.)+[a-z]{2,24}\b/gi) || [];
  domains.forEach((item) => entities.add(normalizeEntity(item)));

  const pathPattern = /(?:^|[\s("'`])((?:\/[a-z0-9][a-z0-9/_\-.?=&%#]*))/gi;
  let match;
  while ((match = pathPattern.exec(text)) !== null) {
    const normalized = normalizeEntity(match[1]);
    if (normalized && normalized !== '/') entities.add(normalized);
  }

  return [...entities].filter(Boolean);
};

const allowedEntitySet = (ids) => {
  const allowed = new Set();

  for (const id of ids) {
    const fact = factMap.get(id);
    if (!fact) continue;

    const values = [
      fact.statement,
      ...collectPrimitiveText(fact.data)
    ];

    for (const value of values) {
      extractEntities(value).forEach((entity) => allowed.add(entity));
    }
  }

  return allowed;
};

const unsupportedEntities = (text, ids) => {
  const entities = extractEntities(text);
  if (!entities.length) return [];

  const allowed = allowedEntitySet(ids);
  return entities.filter((entity) => !allowed.has(entity));
};

const aiIntent = ['ai_traffic', 'ai_sources', 'ai_landing_pages']
  .includes(prepared.classification?.intent);

const hasUnsupportedNoveltyClaim = (value) => {
  if (!aiIntent) return false;
  const text = String(value || '')
    .toLowerCase()
    .replace(/\bnew users?\b/g, 'users');
  const novelty = /\b(new|newly|brand new|first appeared|first-time|first time)\b/.test(text);
  const subject = /\b(ai referral|ai assistant|channel|traffic|dataset|data|source)\b/.test(text);
  return novelty && subject;
};

const idsSupportTopic = (ids, topic) => ids.some((id) => {
  const fact = factMap.get(id);
  if (!fact) return false;
  const data = fact.data || {};
  const statement = String(fact.statement || '').toLowerCase();

  if (topic === 'landing') {
    return Boolean(data.landingPage) ||
      statement.includes('ai referral landing page');
  }

  if (topic === 'source') {
    return Boolean(data.source) || Boolean(data.medium) ||
      statement.includes('ai referral source');
  }

  return true;
});

const textRequiresTopic = (value, topic) => {
  const text = String(value || '').toLowerCase();
  if (topic === 'landing') {
    return /\b(landing page|landing pages|url|urls|specific page|specific pages)\b/.test(text) ||
      extractEntities(text).some((entity) => entity.startsWith('/'));
  }
  if (topic === 'source') {
    return /\b(source|sources|referrer|referrers|domain|domains)\b/.test(text) ||
      extractEntities(text).some((entity) => !entity.startsWith('/'));
  }
  return false;
};

const splitSentences = (text) =>
  String(text || '')
    .replace(/\r/g, '')
    .split(/(?<=[.!?])\s+|\n{2,}/)
    .map((sentence) => sentence.trim())
    .filter(Boolean);

const inspectGrounding = (text, ids) => ({
  unsupportedNumbers: unsupportedNumbers(text, ids),
  unsupportedEntities: unsupportedEntities(text, ids),
  unsupportedNovelty: hasUnsupportedNoveltyClaim(text)
});

const sanitizeGroundedText = (text, ids) => {
  const normalized = normalizeWording(text);
  const sentences = splitSentences(normalized);

  const kept = [];
  const removed = [];

  for (const sentence of sentences) {
    const issues = inspectGrounding(sentence, ids);
    if (
      issues.unsupportedNumbers.length ||
      issues.unsupportedEntities.length ||
      issues.unsupportedNovelty
    ) {
      removed.push({ sentence, ...issues });
    } else {
      kept.push(sentence);
    }
  }

  return {
    text: kept.join(' ').trim(),
    removed
  };
};

const groundingIssues = [];
let rejectedFindings = 0;
let invalidFindingCitations = 0;
let unsupportedFindingNumbers = 0;
let unsupportedFindingEntities = 0;
let unsupportedFindingNovelty = 0;

let findings = [];

for (const item of parsed.findings.slice(0, 8)) {
  const title = normalizeWording(item?.title);
  const detail = normalizeWording(item?.detail);

  const originalIds = Array.isArray(item?.evidenceIds)
    ? item.evidenceIds.map(String)
    : [];

  const evidenceIds = validIds(originalIds);

  if (evidenceIds.length !== originalIds.length) {
    invalidFindingCitations += 1;
  }

  if (!title || !detail || evidenceIds.length === 0) {
    rejectedFindings += 1;
    groundingIssues.push(
      title
        ? `Removed unsupported finding: ${title}`
        : 'Removed an unsupported finding with no valid evidence IDs.'
    );
    continue;
  }

  const titleIssues = inspectGrounding(title, evidenceIds);
  const detailIssues = inspectGrounding(detail, evidenceIds);
  const badNumbers = [
    ...titleIssues.unsupportedNumbers,
    ...detailIssues.unsupportedNumbers
  ];
  const badEntities = [
    ...titleIssues.unsupportedEntities,
    ...detailIssues.unsupportedEntities
  ];
  const badNovelty =
    titleIssues.unsupportedNovelty ||
    detailIssues.unsupportedNovelty;
  const combinedFindingText = `${title} ${detail}`;
  const missingLandingSupport =
    textRequiresTopic(combinedFindingText, 'landing') &&
    !idsSupportTopic(evidenceIds, 'landing');
  const missingSourceSupport =
    textRequiresTopic(combinedFindingText, 'source') &&
    !idsSupportTopic(evidenceIds, 'source');

  if (
    badNumbers.length ||
    badEntities.length ||
    badNovelty ||
    missingLandingSupport ||
    missingSourceSupport
  ) {
    rejectedFindings += 1;
    unsupportedFindingNumbers += badNumbers.length;
    unsupportedFindingEntities += badEntities.length;
    unsupportedFindingNovelty += badNovelty ? 1 : 0;

    const reasons = [];
    if (badNumbers.length) reasons.push(`numbers: ${[...new Set(badNumbers)].join(', ')}`);
    if (badEntities.length) reasons.push(`entities: ${[...new Set(badEntities)].join(', ')}`);
    if (badNovelty) reasons.push('an unsupported new-channel claim');
    if (missingLandingSupport) reasons.push('missing landing-page evidence');
    if (missingSourceSupport) reasons.push('missing source evidence');

    groundingIssues.push(
      `Removed finding "${title}" because it contained unsupported ${reasons.join('; ')}.`
    );
    continue;
  }

  findings.push({
    title,
    detail,
    evidenceIds
  });
}

const findingIds = validIds(
  findings.flatMap((finding) => finding.evidenceIds)
);

let answerEvidenceIds = validIds(parsed.answerEvidenceIds);
if (!answerEvidenceIds.length) {
  answerEvidenceIds = findingIds;
}

const sanitizedAnswer = sanitizeGroundedText(
  parsed.answer,
  answerEvidenceIds
);

let answer = sanitizedAnswer.text;

if (!answer) {
  const safeFindingText = findings
    .slice(0, 3)
    .map((finding) => finding.detail)
    .join(' ');

  if (safeFindingText) {
    answer = safeFindingText;
  } else {
    const fallbackFacts = facts.slice(0, 4);
    answer = fallbackFacts.length
      ? fallbackFacts.map((fact) => fact.statement).join(' ')
      : 'The available evidence was not sufficient to produce a fully grounded answer.';
    answerEvidenceIds = fallbackFacts.map((fact) => fact.id);
  }
}

if (sanitizedAnswer.removed.length) {
  groundingIssues.push(
    `Removed ${sanitizedAnswer.removed.length} answer sentence(s) containing unsupported claims.`
  );
}

const deterministicTables = Array.isArray(prepared.deterministicTables)
  ? prepared.deterministicTables
  : [];
const landingTable = deterministicTables.find((table) =>
  table?.id === 'ai-referral-landing-pages'
);
const sourceTable = deterministicTables.find((table) =>
  table?.id === 'ai-referral-sources'
);
const landingRows = Array.isArray(landingTable?.rows) ? landingTable.rows : [];
const sourceRows = Array.isArray(sourceTable?.rows) ? sourceTable.rows : [];
const landingEvidenceIds = validIds(
  landingRows.flatMap((row) => row?.evidenceIds || [])
);
const sourceEvidenceIds = validIds(
  sourceRows.flatMap((row) => row?.evidenceIds || [])
);
const unavailablePattern = /\b(not available|not provided|does not include|cannot determine|unable to identify|unavailable)\b/i;
const answerClaimsUnavailable = unavailablePattern.test(String(parsed.answer || ''));
const answerUsesLandingEvidence = answerEvidenceIds.some((id) =>
  landingEvidenceIds.includes(id)
);
const answerUsesSourceEvidence = answerEvidenceIds.some((id) =>
  sourceEvidenceIds.includes(id)
);

const sessionLabel = (value) => `${value} session${Number(value) === 1 ? '' : 's'}`;
const describeRows = (rows, entityKey) => rows.slice(0, 3).map((row) => {
  const metrics = [];
  if (row.sessions !== null && row.sessions !== undefined) {
    metrics.push(sessionLabel(row.sessions));
  }
  if (row.engagementRate !== null && row.engagementRate !== undefined) {
    metrics.push(`${row.engagementRate}% engagement rate`);
  }
  if (row.conversions !== null && row.conversions !== undefined) {
    metrics.push(`${row.conversions} conversions`);
  }
  const entity = row?.[entityKey];
  return metrics.length
    ? `${entity} (${metrics.join(', ')})`
    : String(entity || '');
}).filter(Boolean);

let deterministicLandingFallback = false;
let deterministicSourceFallback = false;
let noLandingEvidence = false;
let noSourceEvidence = false;

if (prepared.classification?.intent === 'ai_landing_pages') {
  if (landingRows.length > 0 && (answerClaimsUnavailable || !answerUsesLandingEvidence)) {
    const describedRows = describeRows(landingRows, 'page');
    answer = `The leading AI referral landing pages in the returned rows were ${describedRows.join('; ')}.`;
    answerEvidenceIds = landingEvidenceIds;
    deterministicLandingFallback = true;
    groundingIssues.push(
      'Replaced an unsupported landing-page availability response with deterministic landing-page evidence.'
    );

    if (!findings.some((finding) =>
      finding.evidenceIds.some((id) => landingEvidenceIds.includes(id))
    )) {
      findings = [{
        title: 'Top AI referral landing pages',
        detail: answer,
        evidenceIds: landingEvidenceIds
      }, ...findings].slice(0, 4);
    }
  }

  if (landingRows.length === 0) {
    const absenceFact = facts.find((fact) =>
      fact?.data?.dataset === 'aiLandingPages' &&
      Number(fact?.data?.availableRows) === 0
    );
    answer = absenceFact?.statement ||
      'No AI referral landing-page rows were available in the cached GA4 evidence for the selected period.';
    answerEvidenceIds = absenceFact ? [absenceFact.id] : [];
    findings = [];
    noLandingEvidence = true;
  }
}

if (prepared.classification?.intent === 'ai_sources') {
  if (sourceRows.length > 0 && (answerClaimsUnavailable || !answerUsesSourceEvidence)) {
    const describedRows = describeRows(sourceRows, 'source');
    answer = `The leading AI referral sources in the returned rows were ${describedRows.join('; ')}.`;
    answerEvidenceIds = sourceEvidenceIds;
    deterministicSourceFallback = true;
    groundingIssues.push(
      'Replaced an unsupported source availability response with deterministic AI referral source evidence.'
    );

    if (!findings.some((finding) =>
      finding.evidenceIds.some((id) => sourceEvidenceIds.includes(id))
    )) {
      findings = [{
        title: 'Top AI referral sources',
        detail: answer,
        evidenceIds: sourceEvidenceIds
      }, ...findings].slice(0, 4);
    }
  }

  if (sourceRows.length === 0) {
    const absenceFact = facts.find((fact) =>
      fact?.data?.dataset === 'aiSources' &&
      Number(fact?.data?.availableRows) === 0
    );
    answer = absenceFact?.statement ||
      'No AI referral source rows were available in the cached GA4 evidence for the selected period.';
    answerEvidenceIds = absenceFact ? [absenceFact.id] : [];
    findings = [];
    noSourceEvidence = true;
  }
}

const findingIdsAfterFallback = validIds(
  findings.flatMap((finding) => finding.evidenceIds)
);

let rejectedRecommendations = 0;
let invalidRecommendationCitations = 0;
let removedRecommendationSentences = 0;
let unsupportedRecommendationEntities = 0;
let unsupportedRecommendationNovelty = 0;
const recommendations = [];

for (const item of parsed.recommendations.slice(0, 8)) {
  if (noLandingEvidence || noSourceEvidence) break;

  const originalIds = Array.isArray(item?.evidenceIds)
    ? item.evidenceIds.map(String)
    : [];
  const evidenceIds = validIds(originalIds);

  if (evidenceIds.length !== originalIds.length) {
    invalidRecommendationCitations += 1;
  }

  if (!evidenceIds.length) {
    rejectedRecommendations += 1;
    groundingIssues.push('Removed a recommendation with no valid evidence IDs.');
    continue;
  }

  const recommendationText = `${item?.action || ''} ${item?.rationale || ''}`;
  const missingLandingSupport =
    textRequiresTopic(recommendationText, 'landing') &&
    !idsSupportTopic(evidenceIds, 'landing');
  const missingSourceSupport =
    textRequiresTopic(recommendationText, 'source') &&
    !idsSupportTopic(evidenceIds, 'source');

  if (missingLandingSupport || missingSourceSupport) {
    rejectedRecommendations += 1;
    groundingIssues.push(
      `Removed a recommendation with ${missingLandingSupport ? 'no landing-page evidence' : 'no source evidence'}.`
    );
    continue;
  }

  const actionResult = sanitizeGroundedText(item?.action, evidenceIds);
  const rationaleResult = sanitizeGroundedText(item?.rationale, evidenceIds);

  removedRecommendationSentences +=
    actionResult.removed.length +
    rationaleResult.removed.length;

  for (const removed of [...actionResult.removed, ...rationaleResult.removed]) {
    unsupportedRecommendationEntities += removed.unsupportedEntities?.length || 0;
    unsupportedRecommendationNovelty += removed.unsupportedNovelty ? 1 : 0;
  }

  const action = actionResult.text;
  const rationale = rationaleResult.text ||
    'This action follows from the verified findings and supporting evidence.';

  if (!action) {
    rejectedRecommendations += 1;
    continue;
  }

  recommendations.push({
    priority: ['high', 'medium', 'low'].includes(item?.priority)
      ? item.priority
      : 'medium',
    action,
    rationale,
    evidenceIds
  });
}

if (removedRecommendationSentences) {
  groundingIssues.push(
    `Removed ${removedRecommendationSentences} recommendation sentence(s) containing unsupported claims.`
  );
}

const limitationMatchesDomain = (value) => {
  const text = String(value || '').toLowerCase();
  const domain = prepared.classification?.domain || 'combined';

  if (hasUnsupportedNoveltyClaim(text)) return false;

  if (domain === 'gsc') {
    const ga4OnlyTerms = [
      'ga4',
      'google analytics',
      'session medium',
      'ai-assistant session',
      'ai referral session',
      'engagement rate',
      'source/medium rows',
      'channel rows'
    ];

    if (ga4OnlyTerms.some((term) => text.includes(term))) {
      return false;
    }
  }

  if (domain === 'ga4') {
    const gscOnlyTerms = [
      'search console',
      'gsc ',
      'query rows',
      'page-query',
      'anonymized',
      'keyword counts',
      'average search position'
    ];

    if (gscOnlyTerms.some((term) => text.includes(term))) {
      return false;
    }
  }

  return true;
};

const modelLimitations = parsed.limitations
  .map(String)
  .map(normalizeWording)
  .filter(Boolean)
  .filter(limitationMatchesDomain)
  .slice(0, 4);

const limitations = [...new Set([
  ...prepared.limitations,
  ...modelLimitations
])].slice(0, 8);

const recommendationIds = validIds(
  recommendations.flatMap((item) => item.evidenceIds)
);
const allAcceptedIds = validIds([
  ...answerEvidenceIds,
  ...findingIdsAfterFallback,
  ...recommendationIds
]);
const citedIds = new Set(allAcceptedIds);

const supportingData = facts
  .filter((fact) => citedIds.has(String(fact.id)))
  .slice(0, 24);

const hasLimitedCitedEvidence = supportingData.some((fact) =>
  fact.reliability && fact.reliability !== 'high'
);

const evidencePartial =
  prepared.evidencePartial === true ||
  hasLimitedCitedEvidence;

const groundingAdjusted =
  rejectedFindings > 0 ||
  invalidFindingCitations > 0 ||
  unsupportedFindingNumbers > 0 ||
  unsupportedFindingEntities > 0 ||
  unsupportedFindingNovelty > 0 ||
  sanitizedAnswer.removed.length > 0 ||
  rejectedRecommendations > 0 ||
  invalidRecommendationCitations > 0 ||
  removedRecommendationSentences > 0 ||
  deterministicLandingFallback ||
  deterministicSourceFallback;

const groundingPassed =
  answer.length > 0 &&
  answerEvidenceIds.length > 0 &&
  findings.every((finding) => finding.evidenceIds.length > 0) &&
  recommendations.every((item) => item.evidenceIds.length > 0);

const modelConfidence = ['high', 'medium', 'low'].includes(
  parsed.confidence
)
  ? parsed.confidence
  : 'medium';

let confidence = modelConfidence;
const confidenceReasons = [];

if (prepared.evidencePartial === true) {
  confidenceReasons.push('Relevant analytics evidence is partial.');
}

if (hasLimitedCitedEvidence) {
  confidenceReasons.push(
    'One or more cited facts are based on truncated returned rows.'
  );
}

if (groundingAdjusted) {
  confidenceReasons.push(
    'The grounding guard removed or corrected unsupported model content.'
  );
}

if (noLandingEvidence || noSourceEvidence) {
  confidence = 'low';
  confidenceReasons.push(
    noLandingEvidence
      ? 'No AI referral landing-page rows were available.'
      : 'No AI referral source rows were available.'
  );
} else if (confidence === 'high' && (evidencePartial || groundingAdjusted)) {
  confidence = 'medium';
}

if (!groundingPassed || (findings.length === 0 && groundingAdjusted && !noLandingEvidence && !noSourceEvidence)) {
  confidence = 'low';
}

const deterministicSuggestions = Array.isArray(prepared.suggestedQuestionOptions)
  ? prepared.suggestedQuestionOptions
      .map(String)
      .map(normalizeWording)
      .filter(Boolean)
  : [];

const modelSuggestions = parsed.suggestedQuestions
  .map(String)
  .map(normalizeWording)
  .filter(Boolean);

const suggestedQuestions = aiIntent
  ? deterministicSuggestions.slice(0, 4)
  : modelSuggestions.slice(0, 6);

let tables = deterministicTables;
if (prepared.classification?.intent === 'ai_landing_pages') {
  tables = landingTable ? [landingTable] : [];
} else if (prepared.classification?.intent === 'ai_sources') {
  tables = sourceTable ? [sourceTable] : [];
}

return [{
  json: {
    ok: true,
    requestId: request.requestId,
    question: request.question,
    classification: prepared.classification,
    answer,
    answerEvidenceIds,
    findings,
    recommendations,
    supportingData,
    tables,
    evidenceAvailability: prepared.evidenceAvailability || null,
    confidence,
    limitations,
    suggestedQuestions,
    grounding: {
      passed: groundingPassed,
      adjusted: groundingAdjusted,
      rejectedFindings,
      invalidFindingCitations,
      unsupportedFindingNumbers,
      unsupportedFindingEntities,
      unsupportedFindingNovelty,
      rejectedRecommendations,
      invalidRecommendationCitations,
      unsupportedRecommendationEntities,
      unsupportedRecommendationNovelty,
      removedAnswerSentences: sanitizedAnswer.removed.length,
      removedRecommendationSentences,
      deterministicLandingFallback,
      deterministicSourceFallback,
      issues: groundingIssues.slice(0, 12)
    },
    meta: {
      clientId: request.clientId,
      projectId: prepared.parentMeta.projectId || request.clientId,
      projectName: prepared.parentMeta.projectName || null,
      from: request.from,
      to: request.to,
      partial: prepared.evidencePartial === true,
      overallParentPartial: prepared.parentPartial === true,
      evidenceCache: prepared.evidenceCache || null,
      modelVersion: apiResponse.modelVersion || null,
      generatedAt: new Date().toISOString()
    },
    debug: request.debug ? {
      selectionCounts: prepared.selectionCounts,
      usageMetadata: apiResponse.usageMetadata || null,
      finishReason,
      modelConfidence,
      confidenceAdjusted: confidence !== modelConfidence,
      confidenceReasons,
      sourcePartial: prepared.sourcePartial || null,
      evidenceCache: prepared.evidenceCache || null,
      evidenceAvailability: prepared.evidenceAvailability || null,
      answerableTopics: prepared.answerableTopics || [],
      grounding: {
        groundingPassed,
        groundingAdjusted,
        rejectedFindings,
        invalidFindingCitations,
        unsupportedFindingNumbers,
        unsupportedFindingEntities,
        unsupportedFindingNovelty,
        rejectedRecommendations,
        invalidRecommendationCitations,
        unsupportedRecommendationEntities,
        unsupportedRecommendationNovelty,
        removedAnswerSentences: sanitizedAnswer.removed.length,
        removedRecommendationSentences,
        deterministicLandingFallback,
        deterministicSourceFallback,
        rawAnswerEvidenceIds: parsed.answerEvidenceIds,
        acceptedAnswerEvidenceIds: answerEvidenceIds
      }
    } : undefined
  }
}];

const request = $input.first().json;

return [{
  json: {
    requestId: request.requestId,
    cacheRequest: request.cacheRequest
  }
}];

const prepared = $input.first().json || {};
const request = prepared.request || $('Validate & Normalize Request').first().json;
const facts = Array.isArray(prepared.deterministicFacts)
  ? prepared.deterministicFacts
  : [];
const tables = Array.isArray(prepared.deterministicTables)
  ? prepared.deterministicTables
  : [];
const intent = prepared.classification?.intent || 'ai_traffic';
const projectName =
  prepared.parentMeta?.projectName ||
  prepared.parentMeta?.projectId ||
  request.clientId;

const factById = new Map(facts.map((fact) => [String(fact.id), fact]));
const metricFact = (metric) => facts.find((fact) => fact?.data?.metric === metric) || null;
const sourceTable = tables.find((table) => table.id === 'ai-referral-sources') || null;
const landingTable = tables.find((table) => table.id === 'ai-referral-landing-pages') || null;
const sourceRows = Array.isArray(sourceTable?.rows) ? sourceTable.rows : [];
const landingRows = Array.isArray(landingTable?.rows) ? landingTable.rows : [];

const sessionFact = metricFact('sessions');
const userFact = metricFact('users');
const engagementFact = metricFact('engagementRate');
const conversionFact = metricFact('conversions');
const totalSessions = Number(sessionFact?.data?.value ?? 0) || 0;
const totalUsers = Number(userFact?.data?.value ?? 0) || 0;
const engagementRate = Number(engagementFact?.data?.value ?? 0) || 0;
const conversions = Number(conversionFact?.data?.value ?? 0) || 0;

const formatSource = (value) => String(value || '')
  .replace(/\s*\/\s*ai-assistant$/i, '')
  .replace(/^chatgpt\.com$/i, 'ChatGPT')
  .replace(/^gemini\.google\.com$/i, 'Gemini')
  .replace(/^perplexity\.ai$/i, 'Perplexity');

const plural = (value, singular, pluralValue = `${singular}s`) =>
  `${value} ${Number(value) === 1 ? singular : pluralValue}`;

const uniqueIds = (ids) => [...new Set(
  (ids || []).map(String).filter((id) => factById.has(id))
)];

const finding = (title, detail, evidenceIds) => ({
  title,
  detail,
  evidenceIds: uniqueIds(evidenceIds)
});

const recommendation = (priority, title, detail, evidenceIds) => ({
  priority,
  title,
  detail,
  evidenceIds: uniqueIds(evidenceIds)
});

let answer = '';
let answerEvidenceIds = [];
let findings = [];
let recommendations = [];
let responseTables = [];

if (intent === 'ai_sources') {
  const topRows = sourceRows.slice(0, 5);
  if (topRows.length) {
    const sourceSummary = topRows
      .map((row) => `${formatSource(row.source)} (${plural(row.sessions || 0, 'session')})`)
      .join(', ');
    const leader = topRows[0];
    const leaderShare = totalSessions > 0
      ? Math.round(((Number(leader.sessions) || 0) / totalSessions) * 100)
      : 0;

    answer = `AI referral traffic to ${projectName} came from ${sourceSummary}. ` +
      `${formatSource(leader.source)} was the largest source with ${plural(leader.sessions || 0, 'session')}` +
      `${leaderShare ? `, about ${leaderShare}% of the ${totalSessions} AI referral sessions` : ''}. ` +
      `Overall AI referral engagement was ${engagementRate}%, with ${conversions} conversions recorded.`;

    answerEvidenceIds = uniqueIds([
      sessionFact?.id,
      engagementFact?.id,
      conversionFact?.id,
      ...topRows.flatMap((row) => row.evidenceIds || [])
    ]);

    findings.push(finding(
      `${formatSource(leader.source)} led AI referrals`,
      `${formatSource(leader.source)} generated ${plural(leader.sessions || 0, 'session')} and had a ${Number(leader.engagementRate) || 0}% engagement rate.`,
      leader.evidenceIds
    ));

    if (topRows.length > 1) {
      findings.push(finding(
        'Other AI referral sources contributed smaller volumes',
        topRows.slice(1).map((row) =>
          `${formatSource(row.source)} generated ${plural(row.sessions || 0, 'session')}`
        ).join(', ') + '.',
        topRows.slice(1).flatMap((row) => row.evidenceIds || [])
      ));
    }

    findings.push(finding(
      'AI referral engagement and conversions',
      `AI referral traffic recorded a ${engagementRate}% engagement rate and ${conversions} conversions.`,
      [engagementFact?.id, conversionFact?.id]
    ));

    recommendations.push(recommendation(
      'medium',
      'Review the experience for the largest AI referral source',
      `Review the pages and journeys used by visitors from ${formatSource(leader.source)}. Keep conclusions cautious because the total sample is ${totalSessions} sessions.`,
      [sessionFact?.id, ...(leader.evidenceIds || [])]
    ));

    const zeroEngagementRows = topRows.filter((row) => Number(row.engagementRate) === 0 && Number(row.sessions) > 0);
    if (zeroEngagementRows.length) {
      recommendations.push(recommendation(
        'medium',
        'Investigate low-engagement AI referrals',
        `${zeroEngagementRows.map((row) => formatSource(row.source)).join(', ')} recorded sessions but no engaged sessions in this period.`,
        zeroEngagementRows.flatMap((row) => row.evidenceIds || [])
      ));
    }

    responseTables = [sourceTable];
  } else {
    answer = `No source-level AI referral rows were available for ${projectName} in the selected period.`;
    answerEvidenceIds = uniqueIds([sessionFact?.id]);
  }
} else if (intent === 'ai_landing_pages') {
  const actualRows = landingRows.filter((row) => row.page && row.page !== '(not set)');
  const unresolvedRows = landingRows.filter((row) => row.page === '(not set)');
  const topRows = actualRows.slice(0, 5);

  if (topRows.length) {
    const pageSummary = topRows
      .map((row) => `${row.page} (${plural(row.sessions || 0, 'session')})`)
      .join(', ');
    answer = `The top identified landing pages for AI referral traffic to ${projectName} were ${pageSummary}.`;
    if (unresolvedRows.length) {
      const unresolved = unresolvedRows[0];
      answer += ` GA4 also recorded ${plural(unresolved.sessions || 0, 'session')} with the landing page shown as “(not set)”.`;
    }

    answerEvidenceIds = uniqueIds([
      ...topRows.flatMap((row) => row.evidenceIds || []),
      ...unresolvedRows.flatMap((row) => row.evidenceIds || [])
    ]);

    findings.push(finding(
      'Homepage received the most identified AI referral sessions',
      `${topRows[0].page} received ${plural(topRows[0].sessions || 0, 'session')} with a ${Number(topRows[0].engagementRate) || 0}% engagement rate.`,
      topRows[0].evidenceIds
    ));

    const highEngagement = topRows
      .filter((row) => Number(row.engagementRate) >= 50)
      .slice(0, 3);
    if (highEngagement.length) {
      findings.push(finding(
        'Some AI referral landing pages showed strong observed engagement',
        highEngagement.map((row) =>
          `${row.page} had a ${Number(row.engagementRate) || 0}% engagement rate from ${plural(row.sessions || 0, 'session')}`
        ).join('; ') + '. The volumes are small, so this is directional rather than conclusive.',
        highEngagement.flatMap((row) => row.evidenceIds || [])
      ));
    }

    if (unresolvedRows.length) {
      const unresolved = unresolvedRows[0];
      findings.push(finding(
        'Some AI referral landing pages were unresolved',
        `${plural(unresolved.sessions || 0, 'session')} were attributed to “(not set)”, which limits page-level interpretation.`,
        unresolved.evidenceIds
      ));
      recommendations.push(recommendation(
        'high',
        'Investigate “(not set)” landing-page attribution',
        'Check GA4 session-start and landing-page tracking so more AI referral sessions can be tied to a real page.',
        unresolved.evidenceIds
      ));
    }

    recommendations.push(recommendation(
      'medium',
      'Review the highest-volume AI referral landing pages',
      'Check whether the page content, internal links, and calls to action match the intent of visitors arriving through AI referrals.',
      topRows.slice(0, 3).flatMap((row) => row.evidenceIds || [])
    ));

    responseTables = [landingTable];
  } else {
    answer = `No landing-page-level AI referral rows were available for ${projectName} in the selected period.`;
    answerEvidenceIds = uniqueIds([sessionFact?.id]);
  }
} else {
  answer = `${projectName} recorded ${plural(totalSessions, 'AI referral session')} from ${plural(totalUsers, 'user')} in the selected period. ` +
    `The engagement rate was ${engagementRate}% and ${conversions} conversions were recorded.`;

  answerEvidenceIds = uniqueIds([
    sessionFact?.id,
    userFact?.id,
    engagementFact?.id,
    conversionFact?.id
  ]);

  findings.push(finding(
    'AI referral traffic volume',
    `${projectName} recorded ${plural(totalSessions, 'AI referral session')} from ${plural(totalUsers, 'user')}.`,
    [sessionFact?.id, userFact?.id]
  ));
  findings.push(finding(
    'AI referral engagement',
    `AI referral traffic had a ${engagementRate}% engagement rate.`,
    [engagementFact?.id]
  ));
  findings.push(finding(
    'AI referral conversions',
    `${conversions} conversions were recorded from AI referral traffic.`,
    [conversionFact?.id]
  ));

  recommendations.push(recommendation(
    'medium',
    'Monitor AI referral traffic as the sample grows',
    'Track source, landing-page, engagement, and conversion changes over future periods before drawing strong conclusions.',
    [sessionFact?.id, engagementFact?.id, conversionFact?.id]
  ));

  responseTables = sourceTable ? [sourceTable] : [];
}

answerEvidenceIds = uniqueIds(answerEvidenceIds);
findings = findings.filter((item) => item.evidenceIds.length > 0);
recommendations = recommendations.filter((item) => item.evidenceIds.length > 0);

const citedIds = uniqueIds([
  ...answerEvidenceIds,
  ...findings.flatMap((item) => item.evidenceIds),
  ...recommendations.flatMap((item) => item.evidenceIds)
]);
const supportingData = facts.filter((fact) => citedIds.includes(String(fact.id)));

const limitations = [...new Set([
  ...(Array.isArray(prepared.limitations) ? prepared.limitations : []),
  ...(totalSessions > 0 && totalSessions < 30
    ? [`The AI referral sample is small at ${totalSessions} sessions, so source and engagement patterns are directional.`]
    : []),
  ...(Number(sessionFact?.data?.prev ?? 0) === 0
    ? ['No AI referral sessions were recorded in the comparison period, so a normal period-over-period percentage is not meaningful.']
    : [])
])].slice(0, 6);

let confidence = totalSessions > 0 && totalSessions < 30 ? 'medium' : 'high';
if (!supportingData.length) confidence = 'low';

return [{
  json: {
    ok: true,
    requestId: request.requestId,
    question: request.question,
    classification: prepared.classification,
    answer,
    answerEvidenceIds,
    findings,
    recommendations,
    supportingData,
    tables: responseTables.filter(Boolean),
    evidenceAvailability: prepared.evidenceAvailability || null,
    confidence,
    limitations,
    suggestedQuestions: Array.isArray(prepared.suggestedQuestionOptions)
      ? prepared.suggestedQuestionOptions.slice(0, 4)
      : [],
    grounding: {
      passed: supportingData.length > 0,
      adjusted: false,
      deterministicRoute: true,
      modelBypassed: true,
      issues: []
    },
    meta: {
      clientId: request.clientId,
      projectId: prepared.parentMeta?.projectId || request.clientId,
      projectName: prepared.parentMeta?.projectName || null,
      from: request.from,
      to: request.to,
      partial: prepared.evidencePartial === true,
      overallParentPartial: prepared.parentPartial === true,
      evidenceCache: prepared.evidenceCache || null,
      responseMode: 'deterministic_evidence',
      modelVersion: null,
      generatedAt: new Date().toISOString()
    },
    debug: request.debug ? {
      selectionCounts: prepared.selectionCounts || null,
      sourcePartial: prepared.sourcePartial || null,
      evidenceAvailability: prepared.evidenceAvailability || null,
      answerableTopics: prepared.answerableTopics || [],
      deterministicRoute: true,
      intent
    } : undefined
  }
}];

const failure = $input.first().json || {};
const prepared = $('Prepare Evidence & Facts').first().json || {};
const request = prepared.request || $('Validate & Normalize Request').first().json;
const allFacts = Array.isArray(prepared.deterministicFacts)
  ? prepared.deterministicFacts
  : [];

const suppliedFacts = Array.isArray(failure.supportingData)
  ? failure.supportingData
  : [];
const supportingData = suppliedFacts.length
  ? suppliedFacts
  : allFacts.slice(0, 10);
const evidenceIds = supportingData.map((fact) => String(fact.id)).filter(Boolean);
const firstFacts = supportingData.slice(0, 4);

const answer = String(
  failure.fallbackAnswer ||
  (firstFacts.length
    ? `The language model was temporarily unavailable, but the cached analytics evidence is available. Verified facts: ${firstFacts.map((fact) => fact.statement).join(' ')}`
    : 'The language model was temporarily unavailable and no deterministic facts were available for this question.')
).trim();

const findings = firstFacts.map((fact) => ({
  title: fact.source || 'Verified analytics fact',
  detail: fact.statement,
  evidenceIds: [String(fact.id)]
}));

const limitations = [...new Set([
  ...(Array.isArray(failure.limitations) ? failure.limitations : []),
  'The language model was temporarily unavailable, so this response contains deterministic cached evidence without model interpretation.'
])].slice(0, 6);

return [{
  json: {
    ok: true,
    requestId: request.requestId,
    question: request.question,
    classification: failure.classification || prepared.classification,
    answer,
    answerEvidenceIds: evidenceIds,
    findings,
    recommendations: [],
    supportingData,
    tables: Array.isArray(failure.tables)
      ? failure.tables
      : (Array.isArray(prepared.deterministicTables) ? prepared.deterministicTables : []),
    evidenceAvailability: prepared.evidenceAvailability || null,
    confidence: supportingData.length ? 'medium' : 'low',
    limitations,
    suggestedQuestions: Array.isArray(prepared.suggestedQuestionOptions)
      ? prepared.suggestedQuestionOptions.slice(0, 4)
      : [],
    grounding: {
      passed: supportingData.length > 0,
      adjusted: true,
      deterministicRoute: false,
      modelFallback: true,
      issues: ['The model request failed, so deterministic cached evidence was returned.']
    },
    meta: {
      clientId: request.clientId,
      projectId: prepared.parentMeta?.projectId || request.clientId,
      projectName: prepared.parentMeta?.projectName || null,
      from: request.from,
      to: request.to,
      partial: prepared.evidencePartial === true,
      overallParentPartial: prepared.parentPartial === true,
      evidenceCache: prepared.evidenceCache || null,
      responseMode: 'deterministic_model_fallback',
      modelVersion: null,
      generatedAt: new Date().toISOString()
    },
    debug: request.debug ? {
      modelError: failure.error || null,
      originalCode: failure.code || null,
      apiResponse: failure.debug?.apiResponse || null,
      selectionCounts: prepared.selectionCounts || null,
      evidenceAvailability: prepared.evidenceAvailability || null,
      modelFallback: true
    } : undefined
  }
}];
